import { motion } from 'framer-motion';

const Navbar = () => {
  return (
    <motion.nav 
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      className="fixed top-6 left-1/2 -translate-x-1/2 z-50 bg-white/80 backdrop-blur-md px-6 py-3 rounded-full border border-gray-200 shadow-sm flex gap-8 items-center"
    >
      {['Home', 'About', 'Projects', 'Contact'].map((item) => (
        <a 
          key={item} 
          href={`#${item.toLowerCase()}`} 
          className="text-sm font-medium text-gray-600 hover:text-black transition-colors"
        >
          {item}
        </a>
      ))}
    </motion.nav>
  );
};

export default Navbar;
